import React, { useState, useEffect, useRef } from 'react';
import axios from 'axios';

interface Packet {
  id: number;
  timestamp: string;
  srcIp: string;
  dstIp: string;
  protocol: string;
  length: number;
  prediction: 'normal' | 'anomaly' | 'unknown';
  confidence: number;
  attackType?: string;
}

const LiveCapturePanel: React.FC = () => {
  const [isCapturing, setIsCapturing] = useState(false);
  const [packets, setPackets] = useState<Packet[]>([]);
  const [stats, setStats] = useState({
    total: 0,
    normal: 0,
    anomaly: 0,
    unknown: 0
  });
  const [selectedInterface, setSelectedInterface] = useState('any');
  const [filter, setFilter] = useState('');
  const packetIdRef = useRef(0);

  // Simulate packet capture data
  useEffect(() => {
    if (!isCapturing) return;

    const interval = setInterval(() => {
      // Simulate generating packets
      const newPackets: Packet[] = [];
      const numPackets = Math.floor(Math.random() * 5) + 1;

      for (let i = 0; i < numPackets; i++) {
        packetIdRef.current += 1;
        const rand = Math.random();
        let prediction: 'normal' | 'anomaly' | 'unknown';
        let attackType: string | undefined;

        if (rand < 0.7) {
          prediction = 'normal';
        } else if (rand < 0.9) {
          prediction = 'anomaly';
          const attacks = ['DoS', 'BruteForce', 'SQL Injection', 'XSS', 'Bot'];
          attackType = attacks[Math.floor(Math.random() * attacks.length)];
        } else {
          prediction = 'unknown';
        }

        newPackets.push({
          id: packetIdRef.current,
          timestamp: new Date().toISOString().replace('T', ' ').substring(0, 23),
          srcIp: `192.168.${Math.floor(Math.random() * 255)}.${Math.floor(Math.random() * 255)}`,
          dstIp: `10.0.${Math.floor(Math.random() * 255)}.${Math.floor(Math.random() * 255)}`,
          protocol: ['TCP', 'UDP', 'HTTP', 'HTTPS', 'SSH', 'FTP'][Math.floor(Math.random() * 6)],
          length: Math.floor(Math.random() * 1500) + 64,
          prediction,
          confidence: Math.random() * 0.3 + 0.7,
          attackType
        });
      }

      setPackets(prev => [...newPackets, ...prev].slice(0, 100));
      setStats(prev => ({
        total: prev.total + newPackets.length,
        normal: prev.normal + newPackets.filter(p => p.prediction === 'normal').length,
        anomaly: prev.anomaly + newPackets.filter(p => p.prediction === 'anomaly').length,
        unknown: prev.unknown + newPackets.filter(p => p.prediction === 'unknown').length
      }));
    }, 1000);

    return () => clearInterval(interval);
  }, [isCapturing]);

  const handleStartCapture = () => {
    setIsCapturing(true);
    setPackets([]);
    setStats({ total: 0, normal: 0, anomaly: 0, unknown: 0 });
    packetIdRef.current = 0;
  };

  const handleStopCapture = () => {
    setIsCapturing(false);
  };

  const handleClear = () => {
    setPackets([]);
    setStats({ total: 0, normal: 0, anomaly: 0, unknown: 0 });
    packetIdRef.current = 0;
  };

  const filteredPackets = filter
    ? packets.filter(p => 
        p.srcIp.includes(filter) || 
        p.dstIp.includes(filter) || 
        p.protocol.includes(filter)
      )
    : packets;

  return (
    <div className="live-capture-panel">
      <h2 className="panel-title">
        <span>?</span> Live Capture & Model Detection
      </h2>

      {/* Control Bar */}
      <div className="capture-controls">
        <select
          value={selectedInterface}
          onChange={(e) => setSelectedInterface(e.target.value)}
          className="btn btn-secondary"
          style={{ minWidth: '150px' }}
        >
          <option value="any">All Interfaces</option>
          <option value="eth0">eth0</option>
          <option value="wlan0">wlan0</option>
        </select>

        <input
          type="text"
          placeholder="Filter: IP/Protocol..."
          value={filter}
          onChange={(e) => setFilter(e.target.value)}
          className="btn btn-secondary"
          style={{ flex: 1, maxWidth: '300px' }}
        />

        {!isCapturing ? (
          <button className="btn btn-primary" onClick={handleStartCapture}>
            ? Start Capture
          </button>
        ) : (
          <button className="btn btn-danger" onClick={handleStopCapture}>
            ? Stop Capture
          </button>
        )}

        <button className="btn btn-secondary" onClick={handleClear}>
          ? Clear
        </button>
      </div>

      {/* Status Display */}
      <div className="capture-status">
        <div className={`status-dot ${isCapturing ? 'active' : 'inactive'}`}></div>
        <span>{isCapturing ? 'Capturing network traffic...' : 'Capture stopped'}</span>
        <span style={{ marginLeft: 'auto', color: '#888' }}>
          Interface: {selectedInterface}
        </span>
      </div>

      {/* Stats Cards */}
      <div className="metrics-grid" style={{ marginBottom: '20px' }}>
        <div className="metric-card">
          <div className="metric-value">{stats.total}</div>
          <div className="metric-label">Total Packets</div>
        </div>
        <div className="metric-card">
          <div className="metric-value" style={{ color: '#00ff88' }}>{stats.normal}</div>
          <div className="metric-label">Normal</div>
        </div>
        <div className="metric-card">
          <div className="metric-value" style={{ color: '#ff4757' }}>{stats.anomaly}</div>
          <div className="metric-label">Anomaly</div>
        </div>
        <div className="metric-card">
          <div className="metric-value" style={{ color: '#ffc107' }}>{stats.unknown}</div>
          <div className="metric-label">Unknown</div>
        </div>
      </div>

      {/* Packet List */}
      <div className="packet-list">
        <div className="packet-item" style={{ fontWeight: 'bold', borderBottom: '2px solid #00d4ff' }}>
          <div>Time</div>
          <div>Source</div>
          <div>Destination</div>
          <div>Protocol</div>
          <div>Detection Result</div>
        </div>
        {filteredPackets.length === 0 ? (
          <div style={{ padding: '40px', textAlign: 'center', color: '#666' }}>
            {isCapturing ? 'Waiting for packets...' : 'Click "Start Capture" to begin'}
          </div>
        ) : (
          filteredPackets.map(packet => (
            <div key={packet.id} className="packet-item">
              <div className="packet-time">{packet.timestamp.split(' ')[1]}</div>
              <div className="packet-src">{packet.srcIp}</div>
              <div className="packet-dst">{packet.dstIp}</div>
              <div>{packet.protocol}</div>
              <div>
                <span className={`packet-type ${packet.prediction}`}>
                  {packet.prediction === 'normal' ? '? Normal' : 
                   packet.prediction === 'anomaly' ? `? ${packet.attackType}` : 
                   '? Unknown'}
                </span>
                <span style={{ fontSize: '10px', color: '#666', marginLeft: '5px' }}>
                  {(packet.confidence * 100).toFixed(0)}%
                </span>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default LiveCapturePanel;
